//! The look shared by every Jungey app: dark libadwaita recoloured to deep teal
//! and olive gold, plus a few classes (`jungey-pathbar`, `jungey-statusbar`, ...).

use gtk::gdk;

/// Palette (generated by look/theme.py) followed by the shared rules.
pub const CSS: &str = concat!(include_str!("palette.css"), include_str!("style.css"));

/// Brand colours, for drawing code that can't use CSS.
pub mod color {
    pub const ACCENT: &str = "#c2ca6e";
    pub const ACCENT_BG: &str = "#899041";
    pub const SECOND: &str = "#8ec9d6";
    pub const SUCCESS: &str = "#62b040";
    pub const ERROR: &str = "#d0473a";
    pub const BASE: &str = "#032431";
    pub const VOID: &str = "#01141b";
}

/// Call from the application's `startup` handler.
pub fn init() {
    adw::StyleManager::default().set_color_scheme(adw::ColorScheme::ForceDark);
    let provider = gtk::CssProvider::new();
    provider.load_from_string(CSS);
    if let Some(display) = gdk::Display::default() {
        gtk::style_context_add_provider_for_display(
            &display,
            &provider,
            gtk::STYLE_PROVIDER_PRIORITY_APPLICATION,
        );
    }
}

/// Show a short message at the bottom of a window.
pub fn toast(overlay: &adw::ToastOverlay, text: &str) -> adw::Toast {
    let toast = adw::Toast::new(text);
    toast.set_timeout(3);
    overlay.add_toast(toast.clone());
    toast
}
